fn decimal_to_binary(n: int) -> str {
    """
    Write a function to convert the given decimal number to its binary equivalent, represented as a string with no leading zeros.
    """
    if n == 0 {
        return "0"
    }
    var m = n if n > 0 else -n
    var parts: [str] = []
    while m > 0 {
        parts.append(str(m % 2))
        m = m // 2
    }
    parts.reverse()
    result = "".join(parts)
    return result if n > 0 else "-" + result
}


fn check_min_heap(arr: [int]) -> bool {
    """Check whether the array represents a min heap."""
    n = len(arr)
    for i in range(n) {
        left = 2 * i + 1
        right = 2 * i + 2
        if left < n and arr[i] > arr[left] {
            return False
        }
        if right < n and arr[i] > arr[right] {
            return False
        }
    }
    return True
}


