}


fn circular_shift(x: int, shift: int) -> str {
    """Circular shift the digits of the integer x, shift the digits right by shift
    and return the result as a string.
    If shift > number of digits, return digits reversed.
    >>> circular_shift(12, 1)
    "21"
    >>> circular_shift(12, 2)
    "12"
    """
    s = str(x)
    n = len(s)
    if shift > n {
        return "".join([s[i] for i in range(n - 1, -1, -1)])
    }
    return s[n - shift:] + s[:n - shift]
}


fn even_odd_palindrome(n: int) -> (int, int) {
    """
    Given a positive integer n, return a tuple that has the number of even and odd
    integer palindromes that fall within the range(1, n), inclusive.
    """
    var even = 0
    var odd = 0
    for i in range(1, n + 1) {
        s = str(i)
        var rev = ""
        for c in reversed(s) {
            rev += c
        }
        if rev == s {
            if i % 2 == 0 {
                even += 1
            } else {
                odd += 1
            }
        }
    }
    return (even, odd)
}


fn iscube(a: int) -> bool {
    """
    Write a function that takes an integer a and returns True 
    if this ingeger is a cube of some integer number.
    Note: you may assume the input is always valid.
    Examples:
    >>> iscube(1)
    True
    >>> iscube(2)
    False
    >>> iscube(-1)
    True
    >>> iscube(64)
    True
    >>> iscube(0)
    True
    >>> iscube(180)
    False
    """
    n = abs(a)
    return n == math.pow(n, 1. / 3.).round() ** 3
}


fn parse_nested_parens(paren_string: str) -> [int] {
    """ Input to this function is a string represented multiple groups for nested parentheses separated by spaces.
    For each of the group, output the deepest level of nesting of parentheses.
    E.g. (()()) has maximum two levels of nesting while ((())) has three.

    >>> parse_nested_parens('(()()) ((())) () ((())()())')
    [2, 3, 1, 3]
    """
    var result: [int] = []
    for group in paren_string.split(" ") {
        if group == "" {
            continue
        }
        var depth = 0
        var best = 0
        for c in group {
            if c == "(" {
                depth += 1
                if depth > best {
                    best = depth
                }
            } elif c == ")" {
                depth -= 1
            }
        }
        result.append(best)
    }
    return result
}
